## Description

With interactive reactable tables sticky headers seem to come by default.

With gt I haven't been able to easily find a way to get sticky headers...

## Reproducible example

Example:
```
library(tidyverse)
library(gt)
library(reactable)
library(shiny)

g_output <- gt_output("iris_table")
g_output <- g_output |> 
  htmltools::tagAppendAttributes(style="height:400px;")

r_output <- reactable::reactableOutput("react_table", height = "400px")

ui <- fluidPage(
  shiny::fluidRow(
    column(width=4,
           h4("Great"),
           tags$div(id="great",
                    style="height:400px;",
                    g_output)
           ),
    column(width=4,
           h4("reactable"),
           tags$div(id="react",
                    r_output)
    )
  )
)

server <- function(input, output, session) {
  output$iris_table <- render_gt({
    iris |> 
      gt() |> 
      tab_options(
        container.height = px(400)
      ) |> 
      opt_interactive(use_pagination = FALSE)
  })
  
  output$react_table <- reactable::renderReactable({
    iris |> 
      reactable::reactable(pagination = FALSE)
  })
}

shinyApp(ui, server)
```

This gives me non-sticky headers in the gt half of the experiment:
![image](https://github.com/rstudio/gt/assets/533662/042897ed-a0f6-4efe-b1bd-d397735a2092)

## Expected result

This example (with some jquery runtime hacking) works more as expected:
```
library(tidyverse)
library(gt)
library(reactable)
library(shiny)

g_output <- gt_output("iris_table")
g_output <- g_output |> 
  htmltools::tagAppendAttributes(style="height:400px;")

r_output <- reactable::reactableOutput("react_table", height = "400px")

js_table_hack <- "$(document).ready(function() {
  $('#great').on('DOMNodeInserted', function(e) {
    const t = $(e.target);
    if (t.hasClass('ReactTable')) {
      //console.log('changing the height of an element...');
      //    console.log(t);
      t.css('height','100%');
      t.parent().css('height','100%');
    }
  });
  
});"

ui <- fluidPage(
  tags$header(tags$script(HTML(js_table_hack))),
  shiny::fluidRow(
    column(width=4,
           h4("Great"),
           tags$div(id="great",
                    style="height:400px;",
                    g_output)
           ),
    column(width=4,
           h4("reactable"),
           tags$div(id="react",
                    r_output)
    )
  )
)

server <- function(input, output, session) {
  output$iris_table <- render_gt({
    iris |> 
      gt() |> 
      tab_options(
        container.height = px(400)
      ) |> 
      opt_interactive(use_pagination = FALSE)
  })
  
  output$react_table <- reactable::renderReactable({
    iris |> 
      reactable::reactable(pagination = FALSE)
  })
}

shinyApp(ui, server)
```

